-- Catalog/ledger only. No account or question content.
SELECT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261026000000' AND name='question_practice_adaptation_v2' AND cardinality(statements)=1 AND md5(statements[1])='354934137b8be264f4b1b2cf58d36b2e') AS adaptation_v2_matches,EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261028000000' AND name='course_topic_practice' AND cardinality(statements)=1 AND md5(statements[1])='f8d0fd626747b1dd42fd6f03cf285591') AS course_practice_matches,EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261104000000') AS continuous_recorded,(EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='question_practice_sessions' AND column_name='mode') OR to_regprocedure('public.start_continuous_question_practice(uuid,uuid,uuid)') IS NOT NULL) AS continuous_objects_present;
